/* User identity and capabilities are always supplied by the server. */
window.HANDBOOK_DATA={pages:{},templates:[]};window.HANDBOOK_SOURCES=[];window.PREP_TASKS=[];
window.Access=(()=>{
 let state={user:null,emailAuthAvailable:false,access:{features:{},billingEnabled:false}},ready=false;
 async function load(){
  ready=false;const r=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});const next=await r.json();if(!r.ok)throw Error(next.error||'账户状态读取失败');
  const h=await fetch('/api/handbook',{credentials:'same-origin',cache:'no-store'});const data=await h.json();if(!h.ok)throw Error(data.error||'内容读取失败');
  state=next;window.HANDBOOK_DATA={pages:data.pages,templates:data.templates};window.HANDBOOK_SOURCES=data.sources;window.PREP_TASKS=data.tasks;window.refreshHandbook?.();ready=true;return state;
 }
 function allowed(id){if(!ready)return id==='chapter.overview';return state.access.features[id]?.allowed===true}
 function gateHTML(chapter){const group=window.PREP_NAV.find(g=>g.chapters.some(c=>c[0]===chapter)),label=group?.chapters.find(c=>c[0]===chapter)?.[1]||'完整内容';return '<section class="panel access-gate"><span class="kicker">'+escapeHTML(group?.title||'筹备工作台')+'</span><span class="access-lock" aria-hidden="true">▣</span><h1>'+escapeHTML(label)+'</h1><p>'+escapeHTML(group?.intro||'按章节完成你的筹备计划。')+'</p><div class="gate-preview">本模块包含：'+escapeHTML(group?.chapters.map(c=>c[1]).join(' · ')||label)+'</div><h2>'+(state.user?'此功能暂未向当前账户开放':'登录后查看完整内容')+'</h2><p>'+(state.user?'你可以继续使用账户内已开放的功能。':'注册或登录后，可查看全部章节、勾选待办、保存计划并生成 Word / PDF 方案。当前暂未开启收费。')+'</p>'+(!state.user?'<div class="actions"><button class="btn" data-auth-open="signup">邮箱注册</button><button class="btn secondary" data-auth-open="login">已有账户，登录</button></div>':'')+'</section>'}
 return {load,allowed,gateHTML,get user(){return state.user},get ready(){return ready},get emailAvailable(){return state.emailAuthAvailable},get policy(){return state.access}};
})();
window.Account=(()=>{
 let busy=false,mode='login';const box=()=>document.querySelector('#account-dialog'),esc=x=>escapeHTML(x);
 function paint(){const bar=document.querySelector('#account-bar');if(!bar)return;bar.innerHTML='<a class="account-brand" href="#overview">H / 筹备黑客松指北</a><div class="account-actions">'+(Access.user?'<span class="account-status">'+(Access.policy.billingEnabled?'已登录 · 按账户权限开放':'全部功能已开放 · 暂未收费')+'</span><button class="btn secondary account-button" data-auth-open="account">'+esc(Access.user.name||Access.user.email||'我的账户')+'</button>':'<span class="account-status">先试算，登录后保存完整计划</span><button class="text-btn" data-auth-open="login">登录</button><button class="btn" data-auth-open="signup">邮箱注册</button>')+'</div>'}
 function input(label,name,type,autocomplete,min=0){return '<label>'+label+'<input name="'+name+'" type="'+type+'" autocomplete="'+autocomplete+'" '+(min?'minlength="'+min+'" ':'')+'maxlength="'+(type==='email'?254:type==='password'?128:40)+'" required></label>'}
 function open(next='login'){
  mode=next;const signed=next==='account'&&Access.user;
  box().innerHTML='<div class="export-dialog-head"><div><span class="kicker">筹备黑客松指北</span><h2 id="account-heading">'+(signed?'我的账户':next==='signup'?'创建邮箱账户':'欢迎回来')+'</h2></div><button class="export-close" data-account-close aria-label="关闭账户窗口">×</button></div>'+(signed?'<p class="account-email">'+esc(Access.user.email||'ChatGPT 账户')+'</p><p class="caption">'+(Access.user.provider==='email'?'邮箱密码账户 · 邮箱尚未验证':'通过 ChatGPT 登录 · 保留原有筹备记录')+'</p><div class="account-benefit">'+(Access.policy.billingEnabled?'功能按当前账户权限开放。':'当前登录用户可使用全部功能，尚未开启付费。')+'</div>'+(Access.user.provider==='email'?'<details><summary>修改密码</summary><form data-account-form="password" class="account-form">'+input('当前密码','currentPassword','password','current-password')+input('新密码（12–128 位）','newPassword','password','new-password',12)+input('再次输入新密码','confirm','password','new-password',12)+'<button class="btn" type="submit">保存新密码</button></form></details>':'')+'<button class="btn secondary logout-button" data-account-logout>退出登录</button>':'<p class="account-intro">登录后查看完整指南，保存个人进度，并下载筹备方案。</p><form data-account-form="'+next+'" class="account-form">'+(next==='signup'?input('称呼','name','text','nickname'):'')+input('邮箱','email','email','username')+input(next==='signup'?'密码（12–128 位）':'密码','password','password',next==='signup'?'new-password':'current-password',next==='signup'?12:0)+(next==='signup'?input('再次输入密码','confirm','password','new-password',12):'')+'<button class="btn" type="submit" '+(!Access.emailAvailable?'disabled':'')+'>'+(next==='signup'?'注册并开始筹备':'登录')+'</button></form>'+(!Access.emailAvailable?'<p class="account-feedback">邮箱登录暂不可用，请稍后重试，或使用下方 ChatGPT 登录。</p>':'')+'<p class="caption">邮箱用于登录。当前未启用邮件验证和密码找回，请保存好密码。</p><div class="account-switch">'+(next==='signup'?'已有账户？<button class="text-btn" data-auth-open="login">登录</button>':'还没有账户？<button class="text-btn" data-auth-open="signup">创建账户</button>')+'</div><div class="account-legacy"><a href="/account/chatgpt" target="_top">继续使用 ChatGPT 登录</a><small>已有计划请选择原来的登录方式。邮箱账户与 ChatGPT 账户分别保存进度。</small></div>')+'<p data-account-feedback class="account-feedback" role="status" aria-live="polite"></p>';
  if(!box().open)box().showModal();
 }
 const errorMessages={INVALID_EMAIL_OR_PASSWORD:'邮箱或密码不正确。',USER_ALREADY_EXISTS:'此邮箱已注册，请直接登录。',USER_ALREADY_EXISTS_USE_ANOTHER_EMAIL:'此邮箱已注册，请直接登录。',PASSWORD_TOO_SHORT:'密码至少需要 12 位。',PASSWORD_TOO_LONG:'密码不能超过 128 位。',INVALID_PASSWORD:'当前密码不正确。',INVALID_EMAIL:'请填写有效邮箱。',INVALID_ORIGIN:'登录请求来源不匹配，请刷新后重试。'};
 async function request(path,body){const r=await fetch('/api/auth/'+path,{method:'POST',credentials:'same-origin',signal:AbortSignal.timeout(20000),headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(r.status===429?'尝试次数较多，请一分钟后再试。':errorMessages[data.code]||data.error||'操作未完成，请稍后重试。');return data}
 async function submit(form){if(busy||!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));if(values.confirm!==undefined&&values.confirm!==(values.newPassword||values.password)){box().querySelector('[data-account-feedback]').textContent='两次输入的密码不一致。';return}
  busy=true;box().querySelectorAll('input,button').forEach(el=>el.disabled=true);const feedback=box().querySelector('[data-account-feedback]');feedback.textContent='正在处理…';
  try{const action=form.dataset.accountForm;if(action==='password'){await request('change-password',{currentPassword:values.currentPassword,newPassword:values.newPassword,revokeOtherSessions:true});form.reset();feedback.textContent='密码已修改，其他设备的登录已退出。';return}
   const guest={...Prep.getSettings(),plan:{...planConfig}};delete guest.done;
   await request(action==='signup'?'sign-up/email':'sign-in/email',action==='signup'?{name:values.name.trim(),email:values.email.trim(),password:values.password}:{email:values.email.trim(),password:values.password});
   const current=await fetch('/api/prep-plan',{credentials:'same-origin',cache:'no-store'});if(current.ok){const saved=await current.json();if(Object.keys(saved.state).length===0){const migrated=await fetch('/api/prep-plan',{method:'PATCH',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(guest)});if(!migrated.ok)throw Error('已登录，但试算参数暂未保存，请刷新后重新设置。')}}
   location.reload();
  }catch(e){feedback.textContent=e.message||'操作失败，请重试。'}finally{busy=false;box().querySelectorAll('input,button').forEach(el=>el.disabled=false)}
 }
 async function logout(force=false){if(busy)return;busy=true;const feedback=box().querySelector('[data-account-feedback]');try{if(!force){try{await Promise.race([Prep.flush(),new Promise((_,reject)=>setTimeout(()=>reject(Error('保存尚未完成')),8000))])}catch{feedback.innerHTML='有改动尚未保存。你可以关闭窗口后重试保存，或 <button class="text-btn" data-force-logout>放弃未保存改动并退出</button>';return}}await request('sign-out',{});if(Access.user?.provider==='chatgpt')location.assign('/signout-with-chatgpt?return_to=%2F');else location.reload()}catch(e){feedback.textContent='退出未完成，请检查网络后重试。'}finally{busy=false}}
 document.addEventListener('submit',e=>{if(e.target.matches('[data-account-form]')){e.preventDefault();submit(e.target)}});
 document.addEventListener('click',async e=>{const trigger=e.target.closest('[data-auth-open]');if(trigger&&!busy)open(trigger.dataset.authOpen);if(e.target.closest('[data-account-close]')&&!busy)box().close();if(e.target.closest('[data-account-logout]'))await logout();if(e.target.closest('[data-force-logout]'))await logout(true)});
 document.querySelector('#account-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault()});
 window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});
 return {open,paint};
})();
